import csv
import io


def export_invoices_csv(invoices):
    """Export invoices to CSV with id, customer and total columns."""
    buf = io.StringIO()
    writer = csv.writer(buf)
    writer.writerow(['id', 'customer', 'total'])
    for inv in invoices:
        writer.writerow([inv.id, inv.customer, inv.total])
    return buf.getvalue()

