import heapq


class JobScheduler:
    """Runs jobs in order of their due time using a min-heap."""

    def __init__(self):
        self.heap = []

    def schedule(self, due_at, job):
        heapq.heappush(self.heap, (due_at, job))

    def run_due(self, now):
        while self.heap and self.heap[0][0] <= now:
            _, job = heapq.heappop(self.heap)
            job()
